SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(r),'identity',to_jsonb(pg_identify_object('pg_rewrite'::regclass,r.oid,0)),'relation',to_jsonb(pg_identify_object('pg_class'::regclass,r.ev_class,0)),'definition',pg_get_ruledef(r.oid,false)) ORDER BY r.oid),'[]'::jsonb) AS payload FROM pg_rewrite r WHERE r.ev_class IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture